o+=[f"R {sv+0x10:#x} 8",f"R {sv+0x160:#x} 4",f"R {sv+0x400:#x} 1",f"R {sv+0xa00:#x} 2",f"Q {va:#x} 0xdeadbeef {V("BUFSZ",0x200000):#x}"]
o+=[f"W {sv+0x134:#x} 0",f"W {sv+0x130:#x} 0",f"W {sv+0x10:#x} 0x50000000",f"W {larb:#x} 0xaa01","E"]
